class FieldType {
  constructor(kind, options = {}) {
    this.kind = kind;
    this.options = {
      stored: false,
      ...options,
    };
  }
}

export function TEXT(options = {}) {
  return new FieldType('TEXT', options);
}

export function ID(options = {}) {
  return new FieldType('ID', options);
