class SearchResults {
  constructor(documents) {
    this.documents = documents;
    this.length = documents.length;
  }

  [Symbol.iterator]() {
    return this.documents[Symbol.iterator]();
  }
}

class IndexWriter {
  constructor(index) {
    this.index = index;
    this.pendingDocuments = [];
  }

  add_document(document) {
    this.pendingDocuments.push(this.index.schema.projectDocument(document));
  }

  commit() {
    this.index.documents.push(...this.pendingDocuments);
    this.pendingDocuments = [];
  }
}

class Searcher {
  constructor(index) {
    this.index = index;
  }

  search(query) {
    const matchedDocuments = this.index.documents.filter((document) => query.matches(document));
    return new SearchResults(matchedDocuments);
  }
}

class InMemoryIndex {
  constructor(directory, schema) {
    this.directory = directory;
    this.schema = schema;
    this.documents = [];
  }

  writer() {
    return new IndexWriter(this);
  }

  searcher() {
    return new Searcher(this);
  }
}

export function create_in(directory, schema) {
  return new InMemoryIndex(directory, schema);
}

